$ErrorActionPreference='Stop';if($env:COMPUTERNAME -cne 'DESKTOP-O1LP5DG' -or (Get-CimInstance Win32_ComputerSystemProduct).UUID -cne 'C6440689-D11C-4C63-A463-F3722B7DDB69'){throw 'Wrong builder'};$rows=ConvertFrom-Json ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')));$results=@();foreach($row in $rows){$b=[Convert]::FromBase64String($row.CodeBase64);$sha=[Security.Cryptography.SHA256]::Create();try{$actual=([BitConverter]::ToString($sha.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};if($actual -cne $row.SHA256){throw 'Source hash mismatch'};$text=[Text.Encoding]::UTF8.GetString($b);$tokens=$null;$errors=$null;[void][Management.Automation.Language.Parser]::ParseInput($text,[ref]$tokens,[ref]$errors);$results+=@{Name=$row.Name;SourceSHA256=$actual;ParseErrors=@($errors).Count};if(@($errors).Count){throw ($errors|Out-String)}};[ordered]@{UTC=[DateTime]::UtcNow.ToString('o');PowerShellVersion=$PSVersionTable.PSVersion.ToString();Results=$results;MutationScriptsExecuted=$false}|ConvertTo-Json -Depth 5 -Compress